(() => { const app = window.__CITY_APP, G = window.CITY.GEO; let best = null, nxt = null;
for (const d of G.decks) if (d[0] === 'Gardiner Expressway') { const a = d[3]; for (let i = 0; i + 3 < a.length; i += 3) if (a[i + 2] > 6 && (!best || Math.abs(a[i] - -1300) < Math.abs(best[0] - -1300))) { best = [a[i], a[i + 1], a[i + 2]]; nxt = [a[i + 3], a[i + 4]]; } }
const [gx, gz, gh] = best; const h = Math.atan2(nxt[0] - gx, nxt[1] - gz);
app.teleportTo(gx, gz, h); const e = app.controllerManager.getActiveEntity(); e.position.y = gh;
setTimeout(() => { const p = e.position; const cars = app.trafficSystem.cars.filter((v) => v.edge && (v.y || 0) > 5 && Math.hypot(v.x - p.x, v.z - p.z) < 400);
console.log('[shot] gdr1: player y ' + p.y.toFixed(1) + ' (deck ' + window.CITY.deckHeightAt(p.x, p.z, 60, 0).toFixed(1) + '), speed ' + (e.speed * 3.6).toFixed(0) + ' km/h, ' + cars.length + ' traffic cars up on decks within 400 m'); }, 5500); })()

